#!/bin/sh
# ABOUTME: Prints the Homebrew formula installing atlas VERSION's release binaries,
# ABOUTME: with the checksums from that release's SHA256SUMS file.
set -eu

if [ $# -ne 2 ]; then
  echo "usage: $0 VERSION SHA256SUMS" >&2
  exit 1
fi

version=$1
sums=$2
base="https://github.com/mpenet/atlas/releases/download/v$version"

sum() {
  s=$(awk -v f="$1" '$2 == f {print $1}' "$sums")
  if [ -z "$s" ]; then
    echo "no checksum for $1 in $sums" >&2
    exit 1
  fi
  echo "$s"
}

cat <<EOF
# Generated by the atlas release workflow (tools/brew-formula.sh): don't edit.
class Atlas < Formula
  desc "Call OpenAPI APIs and run Arazzo workflows from the command-line"
  homepage "https://github.com/mpenet/atlas"
  version "$version"
  license "MPL-2.0"

  on_macos do
    on_arm do
      url "$base/atlas-macos-arm64"
      sha256 "$(sum atlas-macos-arm64)"
    end
    on_intel do
      url "$base/atlas-macos-x86_64"
      sha256 "$(sum atlas-macos-x86_64)"
    end
  end

  on_linux do
    on_arm do
      url "$base/atlas-linux-arm64"
      sha256 "$(sum atlas-linux-arm64)"
    end
    on_intel do
      url "$base/atlas-linux-x86_64"
      sha256 "$(sum atlas-linux-x86_64)"
    end
  end

  def install
    # the download is the bare executable, without its mode
    binary = Dir["atlas-*"].first
    chmod 0755, binary
    bin.install binary => "atlas"
    generate_completions_from_executable(bin/"atlas", "completion")
  end

  test do
    assert_match "atlas #{version}", shell_output("#{bin}/atlas --version")
  end
end
EOF
